def test_location_parse_error():
    """Test that LocationParseError is wrapped as InvalidURL"""
    try:
        requests.get("http://fe80::5054:ff:fe5a:fc0")
        print("ERROR: No exception raised for LocationParseError test")
        return False
    except InvalidURL:
        print("✓ LocationParseError wrapped as InvalidURL")
        return True
    except LocationParseError as e:
        print(f"✗ LocationParseError leaked through: {e}")
        return False
    except Exception as e:
        print(f"✗ Unexpected exception: {type(e).__name__}: {e}")
        return False

